const ratingPanel=(kind,id)=>`<section class="section reviews-section"><div class="section-head"><div><span class="eyebrow">Opiniones de la comunidad</span><h2>Calificaciones y comentarios</h2><div>${rating(kind,id)}</div></div></div><div class="grid2"><div class="review-list">${reviews(kind,id).slice().reverse().map(r=>`<div class="review"><div class="topline"><b>${esc(r.name)}</b><span class="rating-stars">${'★'.repeat(r.score)}${'☆'.repeat(5-r.score)}</span></div><p>${esc(r.comment)}</p><small class="muted">${esc(r.date)}</small></div>`).join('')}</div><form class="panel rating-form" data-kind="${attr(kind)}" data-target="${attr(id)}"><h3>Comparte tu experiencia</h3><p class="muted small">Tu opinión ayuda a otras personas a elegir.</p><div class="field"><label>Tu nombre</label><input class="input" name="name" required minlength="2" maxlength="50" placeholder="Ej. Carmen R."></div><div class="field"><label>Tu calificación</label><select class="select" name="score" required><option value="5">★★★★★ Excelente (5)</option><option value="4">★★★★☆ Muy bueno (4)</option><option value="3">★★★☆☆ Bueno (3)</option><option value="2">★★☆☆☆ Regular (2)</option><option value="1">★☆☆☆☆ Malo (1)</option></select></div><div class="field"><label>¿Cómo fue tu experiencia?</label><textarea class="textarea" name="comment" minlength="10" maxlength="400" required placeholder="Cuéntanos qué te pareció..."></textarea></div><button class="btn" type="submit">Publicar mi valoración</button><p class="muted small" style="margin-top:12px">La opinión se guarda en este navegador. No se necesita una cuenta.</p></form></div></section>`;

